      { id: 'rebel', label: '主催者に一矢報いる', fit: function (t) { return t.cp * 0.5 + t.a * 0.5; }, bias: { escape: 2, bond: 1.2 } },
      { id: 'meet', label: '好きな人に会いたい', fit: function (t) { return t.ac * 0.4 + t.fc * 0.4; }, bias: { romance: 2, help: 1.3 }, needsFocus: true }
