    var tieL = (input.ties || []).filter(function (t) { return (t.a === A.i && t.b === B.i) || (t.a === B.i && t.b === A.i); }).sort(function (x, y) { return PRIO.indexOf(x.type) - PRIO.indexOf(y.type); });
