    ST.sayB(S, { actors: [p, b], tag: '恋人', text: F(pk(S, x.t), { a: p.name, b: b.name }), why: p.name + 'と' + b.name + 'は恋人どうし。' + x.why + '（恐怖が少し和らぐ）' }, p.name + 'と' + b.name + 'は寄り添っていた');
