      var c = cat(S, g[0], g[1]), first = ties(S, g[0], g[1])[0], kind = first && first.type === 'crush' ? 'crush' : c || 'close';
      if (g.length > 2) kind = g.some(function (a) { return g.some(function (b) { return a !== b && bond(S, a, b) < -0.2; }); }) ? 'mixed' : 'many';
      var x = g[0], y = g[1];
