      var c = rng() < 0.75 ? HK.weighted(rng, others, function (q) { return 0.2 + Math.max(0, bond(S, q, a)) * 1.5 + q.tr.warmth * 0.5 + (capt(q) ? 0.6 : 0) + (pleaser(q) ? 0.8 : 0); }) : null;
