      stress(p, 3 + (sp.morale < 40 ? 4 : 0) + (sp.food < 20 ? 5 : 0) + (p.m.hp < 50 ? 3 : 0) + (sp.o2 < 30 ? 3 : 0) - (S.planet ? 2 : 0));
