  function mk(ctx, id, a, b) { var d = E[id], t = safe() && SAFE_TXT[id] ? SAFE_TXT[id] : d[1]; return { id: id, title: d[0], text: ctx.t(t, a, b), a: a.i, b: b ? b.i : null }; }
